def merge_chains(a, b):
    placeholder = {"value": None, "next": None}
    tail = placeholder
    while a is not None and b is not None:
        if a["value"] <= b["value"]:
            tail["next"] = a
            a = a["next"]
        else:
            tail["next"] = b
            b = b["next"]
        tail = tail["next"]
    tail["next"] = a if a is not None else b
    return placeholder["next"]
